import listAllContractorsByLoggedImpl from "./listAllContractorsByLoggedImpl";

export const byCompany = (
    {
        company_id,
    }
) => {
    return listAllContractorsByLoggedImpl({
        org_id: {key: 'company_id', value: company_id},
    });
};

