
//<editor-fold desc="site_details_fragment">
const site_details_fragment = `
      id
      status
      contractor{
        id
        name
        username
      }
      site {
        id
        name
        company {
          id
          name
        }
        client {
          id
          name
        }
        project {
          id
          name
        }
      }
`;
//</editor-fold>

//<editor-fold desc="contractor_details_fragment">
export const contractor_details_fragment = ({key, value}) => `
    id
    created_at,
    name
    username
    inc_contractor_pack
    contractor_user_list_aggregate{
      aggregate{
        count
      }
    }
    employee_list_aggregate{
      aggregate{
        count
      }
    }
    questionnaire_list_aggregate:contractor_questionnaire_list_aggregate(where: {group: {_eq: "Contractors"}}){
      aggregate{
        count
      }
    }
    questionnaire_active_list_aggregate:contractor_questionnaire_list_aggregate(where: {group: {_eq: "Contractors"}, status: {_neq: "CompleteAccepted"}}){
      aggregate{
        count
      }
    }
    questionnaire_complete_list_aggregate:contractor_questionnaire_list_aggregate(where: {group: {_eq: "Contractors"}, status: {_eq: "CompleteAccepted"}}){
        aggregate{
          count
        }
    }
    questionnaire_compliance_list_aggregate:contractor_questionnaire_list_aggregate(where: {group: {_eq: "Contractors"}, status: {_eq: "CompleteAccepted"}}){
        nodes {
            id
            question_list_aggregate {
                aggregate {
                    sum {
                        score
                        maxScore
                    }
                    min {
                        score
                    }
                    max {
                        score
                    }
                    avg {
                        score
                    }
                }
            }
        }
    }
    incident_list_aggregate{
      aggregate{
        count
      }
    }
    site_pending_list:site_list(where: {status: {_eq: "Pending"}, site: {${key}: {_eq: $${key}}}}){
      ${site_details_fragment}
    }
    site_accepted_list:site_list(where: {status: {_eq: "Accepted"}, site: {${key}: {_eq: $${key}}}}){
      ${site_details_fragment}
    }
    site_declined_list:site_list(where: {status: {_eq: "Declined"}, site: {${key}: {_eq: $${key}}}}){
      ${site_details_fragment}
    }
    site_cancelled_list:site_list(where: {status: {_eq: "Cancelled"}, site: {${key}: {_eq: $${key}}}}){
      ${site_details_fragment}
    }
    site_removed_list:site_list(where: {status: {_eq: "Removed"}, site: {${key}: {_eq: $${key}}}}){
      ${site_details_fragment}
    }
    site_list(where: {site: {${key}: {_eq: $${key}}}}){
      ${site_details_fragment}
    }
`;
//</editor-fold>

